import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ---------- Elementwise addition (kept for completeness) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ---------- Min reduction (custom CUDA) ----------
min_reduction_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void min_reduction_kernel(const float* input, const int dim_len, float* output, int total_elements) {
    // Naive placeholder: each thread just copies its own element.
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        output[idx] = input[idx];
    }
}

torch::Tensor elementwise_min_cuda(torch::Tensor x, int dim) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    min_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), dim, out.data_ptr<float>(), size);

    return out;
}
"""

min_reduction_cpp_source = "torch::Tensor elementwise_min_cuda(torch::Tensor x, int dim);"
min_reduction_cuda_source = min_reduction_kernel_source
min_reduction_func = load_inline(
    name="elementwise_min_cuda",
    cpp_sources=min_reduction_cpp_source,
    cuda_sources=min_reduction_cuda_source,
    functions=["elementwise_min_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self, dim: int = None):
        super().__init__()
        self.dim = dim if dim is not None else 1
        # Attach the custom CUDA function as an attribute with internal name.
        self.elementwise_min_cuda = min_reduction_func

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.elementwise_min_cuda(x, self.dim)
